CREATE TABLE agent (id text primary key, kind text, name text, cwd text, worktree text, branch text,
        base text, plan text, task text, pid integer, started real, seen real, tx integer);

CREATE TABLE "card" (id integer primary key, job text, task text, kind text, title text, data text check (data is null or json_valid(data)), state text, at real, settled_at real, choice text, ref integer, tx integer, entity integer);

CREATE TABLE "event" (id integer primary key autoincrement, at real, agent text, job text, task text, kind text, summary text, data text check (data is null or json_valid(data)), turn integer, tx integer);

CREATE TABLE "parsed_file" (path text primary key, mtime real);

CREATE TABLE "job" (id text primary key, title text, plan text, repo text, status text, created real, data text check (data is null or json_valid(data)), tx integer);

CREATE TABLE message (id integer primary key, job text, sender text, recipient text, text text,
        state text, reason text, at real, delivered real, read real, acted real, answers integer, tx integer, entity integer);

CREATE TABLE "kv" (key text primary key, value text);

CREATE TABLE review_mark (agent text, path text, state text, hash text, at real, tx integer,
        primary key (agent, path));

CREATE TABLE spend (at real, job text, task text, agent text, provider text, model text,
        input integer, output integer, cost real, status integer, tx integer);

CREATE TABLE tx (
  id integer primary key,
  at real not null,
  actor text not null,
  class text not null,
  session text, profile text, job text,
  project integer,
  tool text,
  req text,
  state text not null default 'committed',
  reverts integer,
  imported integer not null default 0,
  note text,
  answer text);

CREATE TABLE entity (
  n integer primary key,
  id text not null unique,
  kind text not null,
  project integer,
  title text, status text, body text,
  priority integer, assignee text,
  lease_holder text, lease_epoch integer not null default 0, lease_until real,
  data text not null default '{}' check (json_valid(data)),
  field_tx text not null default '{}',
  origin text not null,
  source text,
  ver integer not null,
  created_tx integer not null, updated_tx integer not null, retired_tx integer);

CREATE TABLE entity_hist (
  n integer not null, ver integer not null, tx_from integer not null, tx_to integer not null,
  kind text, project integer, title text, status text, body text,
  priority integer, assignee text, data text, field_tx text,
  lease_holder text, lease_epoch integer, lease_until real, origin text, retired_tx integer,
  primary key (n, ver));

CREATE TABLE link (
  id integer primary key,
  src integer not null, kind text not null, dst integer not null,
  data text check (data is null or json_valid(data)),
  origin text not null, source text,
  tx_from integer not null,
  tx_to integer not null default 4611686018427387904);

CREATE TABLE link_stat (
  src integer not null, kind text not null, dst integer not null,
  count integer not null, first_tx integer not null, last_tx integer not null,
  primary key (src, kind, dst)) without rowid;

CREATE TABLE entity_vec (n integer primary key, bits blob, vec blob, scale real, model text);

CREATE TABLE project_alias (slug text primary key, project integer not null, tx integer not null);

CREATE TABLE excise_log (tx integer primary key, target text not null, fields text, reason text);

CREATE INDEX card_job on card(job, state);

CREATE INDEX event_agent on event(agent, id);

CREATE INDEX event_at on event(at);

CREATE INDEX event_job on event(job, id);

CREATE INDEX event_kind on event(kind, id);

CREATE INDEX message_to on message(recipient, state);

CREATE INDEX spend_job on spend(job);

CREATE INDEX tx_at on tx(at);

CREATE UNIQUE INDEX tx_req on tx(actor, req) where req is not null;

CREATE INDEX entity_kind on entity(project, kind, status);

CREATE INDEX entity_assignee on entity(assignee) where assignee is not null;

CREATE INDEX entity_source on entity(source);

CREATE INDEX entity_hist_tx on entity_hist(n, tx_to);

CREATE UNIQUE INDEX link_cur on link(src, kind, dst) where tx_to = 4611686018427387904;

CREATE INDEX link_out on link(src, kind, tx_to, tx_from);

CREATE INDEX link_in  on link(dst, kind, tx_to, tx_from);

CREATE VIEW file as select path, mtime from parsed_file;

CREATE VIEW meta as select key, value from kv;

CREATE VIEW node as
select e.id as id, e.kind as kind, e.title as title,
  json_extract(e.data, '$.path') as path,
  json_extract(e.data, '$.line') as line,
  e.status as status,
  json_extract(e.data, '$.parent') as parent,
  json_extract(e.data, '$.ord') as ord,
  e.source as source,
  nullif(json_remove(e.data, '$.path', '$.line', '$.parent', '$.ord'), '{}') as data,
  (select t.at from tx t where t.id = e.updated_tx) as updated
from entity e
where e.retired_tx is null
  and (e.kind in ('spec', 'plan', 'step', 'todo', 'ruling', 'commit', 'branch')
       or (e.kind = 'task' and substr(e.id, 1, 6) = 'task:/'));

CREATE VIEW edge as
select case when s.kind = 'file' then substr(s.id, 6) else s.id end as src,
  case when d.kind = 'file' then substr(d.id, 6) else d.id end as dst,
  coalesce(json_extract(l.data, '$.was'), case l.kind when 'on_branch' then 'on-branch' else l.kind end) as kind,
  l.origin as origin,
  l.source as source
from link l join entity s on s.n = l.src join entity d on d.n = l.dst
where l.tx_to = 4611686018427387904 and s.retired_tx is null and d.retired_tx is null
  and (l.kind in ('derives', 'implements', 'on_branch') or json_extract(l.data, '$.was') is not null);

CREATE VIEW jtask as
select substr(e.id, 6) as id,
  json_extract(e.data, '$.job') as job,
  json_extract(e.data, '$.n') as n,
  e.title as title,
  json_extract(e.data, '$.role') as role,
  e.status as status,
  e.assignee as agent,
  e.lease_until as lease_until,
  nullif(json_remove(e.data, '$.job', '$.n', '$.role'), '{}') as data
from entity e
where e.retired_tx is null and e.kind = 'task' and substr(e.id, 1, 6) <> 'task:/'
  and json_extract(e.data, '$.job') is not null;

CREATE VIEW jdep as
select substr(t.id, 6) as task, substr(d.id, 6) as dep
from link l join entity d on d.n = l.src join entity t on t.n = l.dst
where l.kind = 'blocks' and l.tx_to = 4611686018427387904 and d.retired_tx is null and t.retired_tx is null
  and json_extract(t.data, '$.job') is not null and json_extract(d.data, '$.job') is not null;

CREATE VIEW decision as
select json_extract(e.data, '$.n') as n,
  json_extract(e.data, '$.kind') as kind,
  e.title as subject,
  json_extract(e.data, '$.task') as task,
  json_extract(e.data, '$.paths') as paths,
  e.body as reason,
  json_extract(e.data, '$.author') as author,
  e.status as status,
  coalesce((select json_extract(o.data, '$.n') from link l join entity o on o.n = l.dst
            where l.src = e.n and l.kind = 'supersedes' and l.tx_to = 4611686018427387904),
           json_extract(e.data, '$.replaces')) as replaces,
  json_extract(e.data, '$.at') as at,
  json_extract(e.data, '$.ver') as ver,
  json_extract(e.data, '$.job') as job
from entity e
where e.retired_tx is null and e.kind = 'decision';

